import random

def backoff_delay_ms(attempt, base_ms=500, cap_ms=60000):
    return min(cap_ms, base_ms * (2 ** attempt))

def jittered_delay_ms(attempt, base_ms=500, cap_ms=60000):
    cap = backoff_delay_ms(attempt, base_ms, cap_ms)
    return random.uniform(0, cap)

# attempts 0..5 deterministic caps: 500, 1000, 2000, 4000, 8000, 16000

def batching_savings(n_tasks, shots_per_task, per_task_fee, per_shot_fee):
    total_shots = n_tasks * shots_per_task
    unbatched = n_tasks * per_task_fee + total_shots * per_shot_fee
    batched = 1 * per_task_fee + total_shots * per_shot_fee
    savings = unbatched - batched
    pct = (savings / unbatched) * 100
    return {"unbatched": round(unbatched, 2), "batched": round(batched, 2),
            "savings": round(savings, 2), "pct_savings": round(pct, 2)}

