from abc import ABC, abstractmethod
from dataclasses import dataclass
import subprocess, json, qiskit

@dataclass
class NeutralResult:
    counts: dict
    shots: int
    sdk_name: str
    sdk_version: str

class SDKAdapter(ABC):
    @abstractmethod
    def run_bell_pair(self, shots: int) -> NeutralResult:
        raise NotImplementedError

class QiskitAdapter(SDKAdapter):
    def __init__(self, backend):
        self._backend = backend
    def run_bell_pair(self, shots):
        qc = build_bell_pair()
        counts = self._backend.run(qc, shots=shots)
        return NeutralResult(counts=counts, shots=shots, sdk_name="qiskit", sdk_version=qiskit.__version__)

class QSharpAdapter(SDKAdapter):
    def __init__(self, qsharp_env_python: str, script_path: str):
        self._python = qsharp_env_python
        self._script = script_path
    def run_bell_pair(self, shots):
        proc = subprocess.run([self._python, self._script, "--shots", str(shots)],
                               capture_output=True, text=True, check=True)
        data = json.loads(proc.stdout)
        return NeutralResult(counts=data["counts"], shots=shots, sdk_name="qsharp", sdk_version=data["qsharp_version"])

def check_feasibility(circuit, backend, total_shots_estimate, max_reasonable_shots=5_000_000):
    failures = []
    if circuit.num_qubits > backend.num_qubits:
        failures.append(
            f"Circuit needs {circuit.num_qubits} qubits, backend has {backend.num_qubits}"
        )
    estimated_depth = circuit.depth()
    if estimated_depth > getattr(backend, "realistic_noise_tolerant_depth", 1000):
        failures.append(f"Estimated depth {estimated_depth} exceeds backend's noise-tolerant depth")
    if total_shots_estimate > max_reasonable_shots:
        failures.append(
            f"Total shot estimate {total_shots_estimate} exceeds sanity threshold {max_reasonable_shots}"
        )
    return failures
